import os

work_dir = os.environ['BIOAGENT_WORK']
artifacts_dir = os.environ['BIOAGENT_ARTIFACTS']

print("=== WORK DIRECTORY ===")
if os.path.exists(work_dir):
    for item in sorted(os.listdir(work_dir)):
        full_path = os.path.join(work_dir, item)
        if os.path.isdir(full_path):
            print(f"DIR:  {item}")
        else:
            size = os.path.getsize(full_path)
            print(f"FILE: {item} ({size} bytes)")
else:
    print(f"Work directory does not exist: {work_dir}")

print("\n=== ARTIFACTS DIRECTORY ===")
if os.path.exists(artifacts_dir):
    for item in sorted(os.listdir(artifacts_dir)):
        full_path = os.path.join(artifacts_dir, item)
        if os.path.isdir(full_path):
            print(f"DIR:  {item}")
            # List subdirectory contents
            for subitem in sorted(os.listdir(full_path)):
                sub_full = os.path.join(full_path, subitem)
                if os.path.isfile(sub_full):
                    size = os.path.getsize(sub_full)
                    print(f"      {subitem} ({size} bytes)")
        else:
            size = os.path.getsize(full_path)
            print(f"FILE: {item} ({size} bytes)")
else:
