import pandas as pd, os

art = os.environ['BIOAGENT_ARTIFACTS']
td = os.path.join(art, 'tables')

for g, d in [('BC','up'), ('BC','down'), ('Cone','up'), ('Cone','down'), ('MG','up'), ('MG','down'), ('Rod','up'), ('Rod','down')]:
