    for _, r in df.iterrows():
        print(f"  {r['term']:75s} {r['gene_set'].replace('.gmt',''):26s} adjp={r['adj_pval']:.2e} score={r['combined_score']:8.1f} overlap={r['overlap']}")
    print()

import os, glob

work = os.environ['BIOAGENT_WORK']
art = os.environ['BIOAGENT_ARTIFACTS']

print("=== BIOAGENT_WORK contents ===")
for f in sorted(os.listdir(work)):
    print(f)

print("\n=== BIOAGENT_ARTIFACTS contents ===")
for root, dirs, files in os.walk(art):
    for f in sorted(files):
        p = os.path.join(root, f)
        print(os.path.relpath(p, art), os.path.getsize(p))

# Where do tables live?
print("\n=== search for tables dirs ===")
for base in (work, art):
    for root, dirs, files in os.walk(base):
        for f in files:
            if f.endswith('.rnk') or f.endswith('.csv') or f.endswith('.h5ad'):
                p = os.path.join(root, f)
                print(os.path.relpath(p, os.path.dirname(base)), os.path.getsize(p))
